import{_ as e,o as r,c as i,a3 as t}from"./chunks/framework.BlfGB29P.js";const d=JSON.parse('{"title":"XiHan.BasicApp 基础应用","description":"","frontmatter":{},"headers":[],"relativePath":"cosmos/basic-app/index.md","filePath":"cosmos/basic-app/index.md","lastUpdated":1785868852000}'),n={name:"cosmos/basic-app/index.md"};function o(l,a,s,h,p,c){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="xihan-basicapp-基础应用" tabindex="-1">XiHan.BasicApp 基础应用 <a class="header-anchor" href="#xihan-basicapp-基础应用" aria-label="Permalink to &quot;XiHan.BasicApp 基础应用&quot;">​</a></h1><p><strong>企业级中后台内核。</strong> 后端基于 .NET 10 与 <a href="./../framework/">XiHan.Framework</a>，前端基于 Vue 3，开箱即带多租户、RBAC + ABAC 权限、代码生成与实时通信等能力。它既是一套可直接投产的中后台起点，也是学习 .NET + Vue 全栈实践、以及 XiHan.Framework 用法的最佳参考。</p><h2 id="它是什么" tabindex="-1">它是什么 <a class="header-anchor" href="#它是什么" aria-label="Permalink to &quot;它是什么&quot;">​</a></h2><p>XiHan.BasicApp 采用<strong>前后端分离</strong>架构：</p><ul><li><strong>后端</strong> 遵循 DDD 分层与 CQRS，应用服务经<strong>动态 API</strong> 直接暴露为 REST 接口，无需写 Controller</li><li><strong>前端</strong> 使用 Vue 3 + TypeScript + Naive UI，Schema 驱动的列表页、权限/租户/偏好三重感知</li></ul><p>系统内置完整的身份、权限、租户与审计能力。你可以拿它当项目脚手架直接改，也可以只读它的代码学习框架怎么用。</p><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><div class="tip custom-block" style="padding-top:8px;"><ol><li><a href="./getting-started"><strong>快速开始</strong></a> —— 在本地把前后端跑起来（约 10 分钟）</li><li><a href="./architecture"><strong>系统架构</strong></a> —— 看懂后端模块划分与前后端协作</li><li><a href="./permissions"><strong>权限模型</strong></a> —— 理解 RBAC + ABAC、数据范围、多租户隔离</li></ol></div><h2 id="文档地图" tabindex="-1">文档地图 <a class="header-anchor" href="#文档地图" aria-label="Permalink to &quot;文档地图&quot;">​</a></h2><p><strong>入门</strong></p><ul><li><a href="./overview">系统概述</a> —— 定位、技术栈、能力全景、<strong>按角色的阅读路线</strong></li><li><a href="./dev-environment">开发环境</a> —— Docker 起数据库与 Redis</li><li><a href="./getting-started">快速开始</a> —— 跑起来并调通第一个接口</li><li><a href="./project-structure">目录结构与代码地图</a> —— <strong>「我要改 X 该去哪个文件」</strong></li></ul><p><strong>架构</strong></p><ul><li><a href="./architecture">架构总览</a> —— 全景、四条贯穿全局的设计、数据流</li><li><a href="./architecture/backend">后端架构</a> —— 分层、模块装配、DDD、DI 约定、种子</li><li><a href="./architecture/frontend">前端架构</a> —— 五层结构、启动引导、请求时序</li><li><a href="./architecture/request-lifecycle">请求生命周期</a> —— 中间件管道逐段、401/403/423、UoW 收尾</li><li><a href="./architecture/data-model">数据模型</a> —— 实体基类、审计与软删、多租户列、全表清单</li><li><a href="./architecture/caching-async">缓存与异步</a> —— 缓存条目、精准失效、队列消费</li></ul><p><strong>身份与访问</strong></p><ul><li><a href="./identity">身份与认证</a> —— 多种登录、JWT 双令牌、会话、2FA</li><li><a href="./permissions">权限模型</a> —— RBAC + ABAC、权限码、数据范围、字段脱敏</li><li><a href="./organization">组织架构</a> —— 部门树与闭包表、岗位、用户归属</li><li><a href="./multi-tenancy">多租户与版本</a> —— 字段级隔离、租户切换、版本门控</li></ul><p><strong>业务功能</strong></p><ul><li><a href="./messaging">消息中心</a> · <a href="./workflow">工作流</a> · <a href="./approval">审批与约束规则</a></li><li><a href="./file-storage">文件与存储</a> · <a href="./scheduling">任务调度</a> · <a href="./system-settings">系统设置</a></li><li><a href="./open-platform">开放能力</a> · <a href="./audit-log">审计日志</a> · <a href="./code-generation">代码生成</a> · <a href="./ai">AI 能力</a></li></ul><p><strong>前端开发</strong></p><ul><li><a href="./frontend">前端开发指南</a> —— 技术栈、api 层、SignalR、常用组件</li><li><a href="./frontend/schema-page">Schema 驱动页面</a> · <a href="./frontend/routing">路由与菜单</a> · <a href="./frontend/permission">权限与脱敏</a> · <a href="./frontend/theming-i18n">主题与国际化</a></li></ul><p><strong>二次开发与参考</strong></p><ul><li><a href="./development">二次开发</a> —— 加功能纵切片 / 加独立模块 / 加前端页</li><li><a href="./api-guide">接口对接指南</a> —— 响应信封、业务码、<strong>怎么获取 token</strong>、分页协议</li><li><a href="./configuration">配置参考</a> —— <code>appsettings</code> 全量配置节</li><li><a href="./features">功能清单</a> · <a href="./faq">常见问题</a> · <a href="./deployment">部署</a> · <a href="./changelog">更新日志</a></li></ul><h2 id="技术栈速览" tabindex="-1">技术栈速览 <a class="header-anchor" href="#技术栈速览" aria-label="Permalink to &quot;技术栈速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端</th><th>关键技术</th></tr></thead><tbody><tr><td>后端</td><td>.NET 10 · XiHan.Framework 3.5.0 · SqlSugar（PostgreSQL/MySQL/MariaDB）· Redis · SignalR · Serilog · Scalar</td></tr><tr><td>前端</td><td>Vue 3.5+ · TypeScript 6.0+ · Vite 8 · Naive UI · Pinia · Tailwind CSS 4 · Tiptap · vue-i18n</td></tr></tbody></table><h2 id="在线体验" tabindex="-1">在线体验 <a class="header-anchor" href="#在线体验" aria-label="Permalink to &quot;在线体验&quot;">​</a></h2><ul><li><strong>在线用例</strong>：<a href="https://basicapp.xihanfun.com" target="_blank" rel="noreferrer">https://basicapp.xihanfun.com</a></li><li><strong>源码</strong>：<a href="https://github.com/XiHanFun/XiHan.BasicApp" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.BasicApp" target="_blank" rel="noreferrer">Gitee</a></li></ul><h2 id="与-xihan-framework-的关系" tabindex="-1">与 XiHan.Framework 的关系 <a class="header-anchor" href="#与-xihan-framework-的关系" aria-label="Permalink to &quot;与 XiHan.Framework 的关系&quot;">​</a></h2><p>XiHan.BasicApp 构建在 <a href="./../framework/">XiHan.Framework</a> 之上——框架提供认证、授权、数据、缓存、事件总线、多租户、动态 API 等底层能力，BasicApp 在其上实现具体的中后台业务。想先理解底层机制，建议先读<a href="./../framework/quickstart">框架快速上手</a>。</p>',27)])])}const g=e(n,[["render",o]]);export{d as __pageData,g as default};
